// Converte a resposta do Gemini no contrato que o Python espera.
// Sucesso: { ok: true, modelo, resultado, uso }  |  Falha: { ok: false, erro }
const r = $input.first().json;
const status = r.statusCode;
const body = (typeof r.body === 'string') ? (() => { try { return JSON.parse(r.body); } catch (e) { return {}; } })() : (r.body || {});

if (status !== 200) {
  const msg = (body.error && body.error.message) || ('HTTP ' + status);
  return [{ json: { ok: false, erro: 'Gemini HTTP ' + status + ': ' + String(msg).slice(0, 200) } }];
}
const cand = (body.candidates || [])[0];
if (!cand) {
  const motivo = (body.promptFeedback && body.promptFeedback.blockReason) || 'sem resposta';
  return [{ json: { ok: false, erro: 'Gemini bloqueou o pedido: ' + motivo } }];
}
if (cand.finishReason && cand.finishReason !== 'STOP') {
  return [{ json: { ok: false, erro: 'Gemini terminou com ' + cand.finishReason } }];
}
const texto = ((cand.content && cand.content.parts) || [])
  .filter(p => !p.thought)
  .map(p => p.text || '')
  .join('');
let resultado;
try {
  resultado = JSON.parse(texto);
} catch (e) {
  return [{ json: { ok: false, erro: 'Gemini devolveu JSON inválido' } }];
}
return [{ json: { ok: true, modelo: body.modelVersion || null, resultado, uso: body.usageMetadata || null } }];
